using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Diagnostics;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace PZ3D {static class LauncherJournalMergeTests {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=2097152};static int checks,failed;static readonly List<string> failures=new List<string>();static readonly List<object> cases=new List<object>();
 static void Check(bool value,string label){checks++;if(!value){failed++;failures.Add(label);Console.WriteLine("FAIL "+label);}}
 static void Require(bool value,string label){if(!value)throw new Exception("Fixture precondition failed: "+label);}
 static Dictionary<string,object> D(object value){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
 static Dictionary<string,object>[] Rows(object value){return ((IEnumerable)D(value)["history"]).Cast<object>().Select(D).ToArray();}
 static bool Completed(object value,string action){return Rows(value).Any(row=>(string)row["action"]==action&&(string)row["status"]=="completed");}
 static object Summary(object value){if(value==null)return null;return Rows(value).Select(row=>new{Id=row["id"],Action=row["action"],Status=row["status"],Finished=row["finished"],Progress=row["progress"]}).ToArray();}
 static int Child(string root,bool shared){var journal=new LauncherJournal(root);journal.Begin(shared?"B-shared":"B-new","owned other-process journal task");File.WriteAllText(Path.Combine(root,"child-started"),"owned");if(shared){var timeout=Stopwatch.StartNew();while(!File.Exists(Path.Combine(root,"child-continue"))){if(timeout.ElapsedMilliseconds>10000)throw new TimeoutException("Owned merge fixture parent did not release child");Thread.Sleep(10);}}journal.Finish("completed","other process completed");return 0;}
 static Process StartChild(string root,bool shared){return Process.Start(new ProcessStartInfo(System.Reflection.Assembly.GetExecutingAssembly().Location,"--child \""+root+"\" "+(shared?"shared":"new")){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});}
 static void Run(string root,bool shared){Directory.CreateDirectory(root);string file=Path.Combine(root,"diagnostics","tasks.json"),other=shared?"B-shared":"B-new";var journal=new LauncherJournal(root);journal.Begin("A","owned first-process task");Process child=null;object pending=null,diskBefore=null,snapshotBeforeFlush=null,diskAfter=null;try{
  if(shared){child=StartChild(root,true);var timeout=Stopwatch.StartNew();while(!File.Exists(Path.Combine(root,"child-started"))){Require(!child.HasExited&&timeout.ElapsedMilliseconds<5000,"other process must begin its shared-ID task");Thread.Sleep(10);}Require(Rows(LauncherNativeState.Read<LauncherTaskStore>(file,()=>null)).Any(row=>(string)row["action"]==other&&(string)row["status"]=="running"),"shared task is on disk before pending copy");}
  using(var held=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){journal.Finish("completed","actual finish while diagnostic file is held");pending=journal.Snapshot();Check(Completed(pending,"A"),other+": actual A terminal state remains visible during IO failure");Check(!string.IsNullOrWhiteSpace(Convert.ToString(D(pending)["persistenceWarning"])),other+": unsaved warning is explicit");}
  if(shared)File.WriteAllText(Path.Combine(root,"child-continue"),"owned continue");else child=StartChild(root,false);Require(child.WaitForExit(10000)&&child.ExitCode==0,"actual hidden other-process write succeeds");diskBefore=LauncherNativeState.Read<LauncherTaskStore>(file,()=>null);Require(Completed(diskBefore,other),"other process committed complete task before parent retries");snapshotBeforeFlush=journal.Snapshot();Check(Completed(snapshotBeforeFlush,"A")&&Completed(snapshotBeforeFlush,other),other+": read-only Snapshot merges current disk and pending terminal records");Check(!string.IsNullOrWhiteSpace(Convert.ToString(D(snapshotBeforeFlush)["persistenceWarning"])),other+": pending warning remains until actual successful write");string stableSnapshot=Json.Serialize(snapshotBeforeFlush);
  journal.Begin("C","owned next task flushes pending");journal.Finish("completed","retry done");diskAfter=LauncherNativeState.Read<LauncherTaskStore>(file,()=>null);Check(Completed(diskAfter,other),other+": retry retains other process completed history");Check(Completed(diskAfter,"A")&&Completed(diskAfter,"C"),other+": retry persists own pending terminal and new task");Check(!Rows(diskAfter).Any(row=>(string)row["status"]=="running"),other+": terminal task never regresses to stale running");Check(Json.Serialize(snapshotBeforeFlush)==stableSnapshot,other+": captured merged snapshot is immutable after later writes");Check(string.IsNullOrEmpty(Convert.ToString(D(journal.Snapshot())["persistenceWarning"])),other+": successful persistence clears warning");Check(Directory.GetFiles(root,"*.new-*",SearchOption.AllDirectories).Length==0,other+": no replacement staging files remain");
 }finally{if(child!=null){if(!child.HasExited){File.WriteAllText(Path.Combine(root,"child-continue"),"owned cleanup release");Require(child.WaitForExit(12000),"owned child exits during fixture cleanup");}child.Dispose();}cases.Add(new{SharedTaskId=shared,Pending=Summary(pending),DiskBeforeParentRetry=Summary(diskBefore),SnapshotBeforeParentRetry=Summary(snapshotBeforeFlush),DiskAfterParentRetry=Summary(diskAfter)});}}
 static void CorruptRecovery(string root){Directory.CreateDirectory(root);string file=Path.Combine(root,"diagnostics","tasks.json");var journal=new LauncherJournal(root);journal.Begin("A-corrupt","owned corruption recovery task");byte[] original=File.ReadAllBytes(file);using(var held=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read))journal.Finish("completed","pending before external diagnostic corruption");byte[] bad=Encoding.UTF8.GetBytes("{owned invalid journal");File.WriteAllBytes(file,bad);bool typed=false;try{LauncherNativeState.Read<LauncherTaskStore>(file,()=>null);}catch(InvalidDataException error){typed=error.InnerException!=null;}Check(typed,"corrupt JSON keeps a typed IO failure and original parse cause");var pending=journal.Snapshot();Check(Completed(pending,"A-corrupt")&&!string.IsNullOrWhiteSpace(Convert.ToString(D(pending)["persistenceWarning"])),"pending terminal state remains readable with a corrupt disk record");Check(File.ReadAllBytes(file).SequenceEqual(bad),"read-only pending fallback leaves corrupt bytes unchanged");journal.Begin("C-corrupt","owned operation during diagnostic corruption");journal.Finish("completed","operation result independent of diagnostic corruption");Check(Completed(journal.Snapshot(),"C-corrupt"),"corrupt diagnostic disk does not block the next actual task terminal state");Check(File.ReadAllBytes(file).SequenceEqual(bad),"attempted persistence never overwrites corrupt diagnostic bytes");File.WriteAllBytes(file,original);journal.Begin("D-corrupt","owned recovery flush");journal.Finish("completed","recovered");var saved=LauncherNativeState.Read<LauncherTaskStore>(file,()=>null);Check(Completed(saved,"A-corrupt")&&Completed(saved,"C-corrupt")&&Completed(saved,"D-corrupt"),"restored readable disk merges and persists every pending terminal record");Check(string.IsNullOrEmpty(Convert.ToString(D(journal.Snapshot())["persistenceWarning"])),"corruption recovery clears pending warning only after actual persistence");Check(Directory.GetFiles(root,"*.new-*",SearchOption.AllDirectories).Length==0,"corruption recovery leaves no replacement staging files");cases.Add(new{CorruptDiskRecovery=true,FinalDisk=Summary(saved)});}
 public static int Main(string[] args){Console.OutputEncoding=new UTF8Encoding(false);if(args[0]=="--child")return Child(args[1],args[2]=="shared");try{Run(Path.Combine(args[0],"new-id"),false);Run(Path.Combine(args[0],"same-id-terminal"),true);CorruptRecovery(Path.Combine(args[0],"corrupt-disk"));return failed==0?0:1;}catch(Exception error){failed++;failures.Add(error.ToString());return 2;}finally{Console.WriteLine(Json.Serialize(new{passed=failed==0,checks=checks,failed=failed,failures=failures,cases=cases,scope="Actual production LauncherJournal and native files with real replacement failure and hidden other-process journal writes; no game, UI, real user data or synthetic journal methods"}));}}
}}
